1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
12	)
13	
14	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
15	type replicateInput struct {
16		CurrentTerm    int                      `json:"currentTerm"`
17		CommittedIndex int                      `json:"committedIndex"`
18		Log            []mevwatch.LogEntry      `json:"log"`
19		ApplyKV        bool                     `json:"applyKV"`
20		Requests       []mevwatch.AppendRequest `json:"requests"`
21	}
22	
23	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
24	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
25	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
26	func runReplicate() int {
27		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
28	}
29	
30	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
31		data, err := io.ReadAll(stdin)
32		if err != nil {
33			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
34			return 1
35		}
36		var syntaxCheck interface{}
37		if err := json.Unmarshal(data, &syntaxCheck); err != nil {
38			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
39			return 1
40		}
41		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
42		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
43		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
44		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
45		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
46		// 前一份数组，因此重复键的每一次出现都必须单独检查。
47		if path := nullNumericFieldPath(data); path != "" {
48			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
49			return 1
50		}
51		var input replicateInput
52		if err := json.Unmarshal(data, &input); err != nil {
53			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
54			return 1
55		}
56		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
57			CurrentTerm:    input.CurrentTerm,
58			CommittedIndex: input.CommittedIndex,
59			Log:            input.Log,
60		}, input.Requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
61		if err != nil {
62			fmt.Fprintf(stderr, "replicate: %v\n", err)
63			return 1
64		}
65		encoded, err := json.MarshalIndent(output, "", "  ")
66		if err != nil {
67			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
68			return 1
69		}
70		fmt.Fprintln(stdout, string(encoded))
71		return 0
72	}
73	
74	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
75	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
76	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
77	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
78	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
79	// requests[1].leaderCommit。字段名识别与 encoding/json 一致，只改变字母大小
80	// 写的写法同样命中。
81	//
82	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
83	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
84	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
85	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
86	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
87	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
88	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
89	func nullNumericFieldPath(data []byte) string {
90		dec := json.NewDecoder(bytes.NewReader(data))
91	
92		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
93		// 字段位置，交由随后的类型化解码产出既有的解析错误。
94		tok, err := dec.Token()
95		if err != nil || tok != json.Delim('{') {
96			return ""
97		}
98		for dec.More() {
99			key, ok := decodeKey(dec)
100			if !ok {
101				return ""
102			}
103			switch {
104			case strings.EqualFold(key, "currentTerm"), strings.EqualFold(key, "committedIndex"):
105				if nullScalarPath(dec) {
106					return canonicalScalarPath(key)
107				}
108			case strings.EqualFold(key, "log"):
109				if path := scanEntryArray(dec, "log", ""); path != "" {
110					return path
111				}
112			case strings.EqualFold(key, "requests"):
113				if path := scanRequests(dec); path != "" {
114					return path
115				}
116			default:
117				skipValue(dec)
118			}
119		}
120		return ""
121	}
122	
123	// scanRequests 扫描 requests 数组的完整 token 流，包括重复出现时的每一份
124	// 数组，返回其中第一个数值 null 的完整位置。
125	func scanRequests(dec *json.Decoder) string {
126		tok, err := dec.Token()
127		if err != nil {
128			return ""
129		}
130		if tok != json.Delim('[') {
131			// requests 不是数组（如 null）：数组字段本身沿用既有处理，其值仍需
132			// 从 token 流中消费掉。
133			return ""
134		}
135		for i := 0; dec.More(); i++ {
136			tok, err := dec.Token()
137			if err != nil {
138				return ""
139			}
140			if tok != json.Delim('{') {
141				// 非对象请求元素不可能含已识别字段；若它本身是容器仍要消费完整。
142				if d, ok := tok.(json.Delim); ok {
143					skipRest(dec, d)
144				}
145				continue
146			}
147			prefix := fmt.Sprintf("requests[%d]", i)
148			for dec.More() {
149				key, ok := decodeKey(dec)
150				if !ok {
151					return ""
152				}
153				switch {
154				case strings.EqualFold(key, "term"),
155					strings.EqualFold(key, "prevLogIndex"),
156					strings.EqualFold(key, "prevLogTerm"),
157					strings.EqualFold(key, "leaderCommit"):
158					if nullScalarPath(dec) {
159						return prefix + "." + canonicalScalarPath(key)
160					}
161				case strings.EqualFold(key, "entries"):
162					if path := scanEntryArray(dec, "entries", prefix+"."); path != "" {
163						return path
164					}
165				default:
166					skipValue(dec)
167				}
168			}
169			if _, err := dec.Token(); err != nil { // 请求对象的 '}'
170				return ""
171			}
172		}
173		if _, err := dec.Token(); err != nil {
174			return ""
175		}
176		return ""
177	}
178	
179	// scanEntryArray 扫描 log 或 entries 数组的完整 token 流（数组字段重复出现
180	// 时由调用方对每一份数组分别调用），返回第一个 index/term 为 null 的条目
181	// 字段完整位置。arrayName 只用于选择下标前缀的写法：根日志为 log[i]，请求
182	// 条目为 requests[r].entries[i]（parentPrefix 已含 "requests[r]."）。
183	func scanEntryArray(dec *json.Decoder, arrayName, parentPrefix string) string {
184		tok, err := dec.Token()
185		if err != nil {
186			return ""
187		}
188		if tok != json.Delim('[') {
189			return "" // 数组字段本身为 null 或其他类型：沿用既有处理
190		}
191		for i := 0; dec.More(); i++ {
192			tok, err := dec.Token()
193			if err != nil {
194				return ""
195			}
196			if tok != json.Delim('{') {
197				// 非对象条目不可能含已识别字段；若它本身是容器仍要消费完整。
198				if d, ok := tok.(json.Delim); ok {
199					skipRest(dec, d)
200				}
201				continue
202			}
203			prefix := parentPrefix + arrayName + fmt.Sprintf("[%d]", i)
204			for dec.More() {
205				key, ok := decodeKey(dec)
206				if !ok {
207					return ""
208				}
209				if strings.EqualFold(key, "index") || strings.EqualFold(key, "term") {
210					if nullScalarPath(dec) {
211						return prefix + "." + canonicalEntryFieldPath(key)
212					}
213				} else {
214					skipValue(dec)
215				}
216			}
217			if _, err := dec.Token(); err != nil { // 条目对象的 '}'
218				return ""
219			}
220		}
221		if _, err := dec.Token(); err != nil {
222			return ""
223		}
224		return ""
225	}
226	
227	// decodeKey 读取并断言下一个 token 是对象键。
228	func decodeKey(dec *json.Decoder) (string, bool) {
229		tok, err := dec.Token()
230		if err != nil {
231			return "", false
232		}
233		key, ok := tok.(string)
234		return key, ok
235	}
236	
237	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
238	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
239	// 报告既有错误）。
240	func nullScalarPath(dec *json.Decoder) bool {
241		tok, err := dec.Token()
242		if err != nil {
243			return false
244		}
245		if tok == nil {
246			return true
247		}
248		if d, ok := tok.(json.Delim); ok {
249			skipRest(dec, d)
250		}
251		return false
252	}
253	
254	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
255	func skipValue(dec *json.Decoder) {
256		tok, err := dec.Token()
257		if err != nil {
258			return
259		}
260		if d, ok := tok.(json.Delim); ok {
261			skipRest(dec, d)
262		}
263	}
264	
265	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
266	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
267	func skipRest(dec *json.Decoder, open json.Delim) {
268		if open != '{' && open != '[' {
269			return
270		}
271		depth := 1
272		for depth > 0 {
273			tok, err := dec.Token()
274			if err != nil {
275				return
276			}
277			if d, ok := tok.(json.Delim); ok {
278				switch d {
279				case '{', '[':
280					depth++
281				case '}', ']':
282					depth--
283				}
284			}
285		}
286	}
287	
288	// canonicalScalarPath 把命中的根状态或请求数值字段名归一为标准字段名，错误
289	// 位置始终使用标准拼写而不是输入里的大小写变体。
290	func canonicalScalarPath(key string) string {
291		for _, name := range []string{"currentTerm", "committedIndex", "term", "prevLogIndex", "prevLogTerm", "leaderCommit"} {
292			if strings.EqualFold(key, name) {
293				return name
294			}
295		}
296		return key
297	}
298	
299	// canonicalEntryFieldPath 把条目数值字段名归一为 index/term 的标准拼写。
300	func canonicalEntryFieldPath(key string) string {
301		switch {
302		case strings.EqualFold(key, "index"):
303			return "index"
304		case strings.EqualFold(key, "term"):
305			return "term"
306		default:
307			return key
308		}
309	}
