package main

import (
	"bytes"
	"strings"
	"testing"
)

// runReplicateExpectInputError 执行一次 replicate，断言整份输入在读取阶段被
// 拒绝：退出码 1、标准输出没有任何结果 JSON、标准错误带 replicate: 前缀且
// 指出字段的完整位置。
func runReplicateExpectInputError(t *testing.T, input, wantPath string) string {
